     1→/// x86-64 Code Generator for Zig Compiler
     2→/// Converts AIR (Analyzed IR) to x86-64 Assembly (Intel syntax, NASM compatible)
     3→///
     4→/// Architecture:
     5→/// - AIR instructions → x86-64 assembly (.asm file)
     6→/// - Register allocation: rax-r15 (16 registers)
     7→/// - Calling convention: System V AMD64 ABI (rdi, rsi, rdx, rcx, r8, r9 for args)
     8→/// - Output format: NASM Intel syntax (mov rax, rbx)
     9→
    10→const std = @import("std");
    11→const Allocator = std.mem.Allocator;
    12→const ArrayList = std.ArrayList;
    13→
    14→// ============================================================================
    15→// AIR Types (Shared with RISC-V)
    16→// ============================================================================
    17→
    18→pub const Air = struct {
    19→    ref_type: type,
    20→    instructions: ArrayList(Instruction),
    21→};
    22→
    23→pub const Instruction = union(enum) {
    24→    load_int: i64,
    25→    binary_op: struct {
    26→        op: BinaryOp,
    27→        lhs: u32, // ref
    28→        rhs: u32, // ref
    29→    },
    30→    unary_op: struct {
    31→        op: UnaryOp,
    32→        operand: u32,
    33→    },
    34→    function_begin: struct {
    35→        name: []const u8,
    36→        arg_count: u32,
    37→    },
    38→    function_end,
    39→    call: struct {
    40→        target: []const u8,
    41→        arg_count: u32,
    42→    },
    43→    cond_br: struct {
    44→        cond: u32,
    45→        then_label: u32,
    46→        else_label: u32,
    47→    },
    48→    br: u32, // label
    49→    label: u32,
    50→    noop,
    51→};
    52→
    53→pub const BinaryOp = enum {
    54→    add,
    55→    sub,
    56→    mul,
    57→    div,
    58→    mod,
    59→    eq,
    60→    ne,
    61→    lt,
    62→    le,
    63→    gt,
    64→    ge,
    65→};
    66→
    67→pub const UnaryOp = enum {
    68→    negate,
    69→    not,
    70→};
    71→
    72→// ============================================================================
    73→// x86-64 Register Definition
    74→// ============================================================================
    75→
    76→pub const Register = enum(u4) {
    77→    rax = 0,  // return value, accumulator
    78→    rcx = 1,  // counter, 4th arg
    79→    rdx = 2,  // data, 3rd arg
    80→    rbx = 3,  // base (callee-saved)
    81→    rsp = 4,  // stack pointer (reserved)
    82→    rbp = 5,  // frame pointer (reserved)
    83→    rsi = 6,  // 2nd arg
    84→    rdi = 7,  // 1st arg
    85→    r8 = 8,   // 5th arg
    86→    r9 = 9,   // 6th arg
    87→    r10 = 10, // caller-saved (temporary)
    88→    r11 = 11, // caller-saved (temporary)
    89→    r12 = 12, // callee-saved
    90→    r13 = 13, // callee-saved
    91→    r14 = 14, // callee-saved
    92→    r15 = 15, // callee-saved
    93→
    94→    pub fn name(self: Register) []const u8 {
    95→        return switch (self) {
    96→            .rax => "rax", .rcx => "rcx", .rdx => "rdx", .rbx => "rbx",
    97→            .rsp => "rsp", .rbp => "rbp", .rsi => "rsi", .rdi => "rdi",
    98→            .r8 => "r8",   .r9 => "r9",   .r10 => "r10", .r11 => "r11",
    99→            .r12 => "r12", .r13 => "r13", .r14 => "r14", .r15 => "r15",
   100→        };
   101→    }
   102→
   103→    pub fn al(self: Register) []const u8 {
   104→        return switch (self) {
   105→            .rax => "al", .rcx => "cl", .rdx => "dl", .rbx => "bl",
   106→            else => "al", // 나머지는 지원 안 함 (8-bit로 변환 불가)
   107→        };
   108→    }
   109→};
   110→
   111→// ============================================================================
   112→// x86-64 Code Generator
   113→// ============================================================================
   114→
   115→pub const X86_64Codegen = struct {
   116→    allocator: Allocator,
   117→    output: ArrayList(u8),
   118→    used_regs: [16]bool,
   119→    label_counter: u32,
   120→    current_frame_size: i64,
   121→
   122→    pub fn init(allocator: Allocator) X86_64Codegen {
   123→        return X86_64Codegen{
   124→            .allocator = allocator,
   125→            .output = ArrayList(u8).init(allocator),
   126→            .used_regs = [_]bool{false} ** 16,
   127→            .label_counter = 0,
   128→            .current_frame_size = 0,
   129→        };
   130→    }
   131→
   132→    pub fn deinit(self: *X86_64Codegen) void {
   133→        self.output.deinit();
   134→    }
   135→
   136→    // Allocate a free register
   137→    pub fn allocReg(self: *X86_64Codegen) ?Register {
   138→        // Prefer temp registers: r10, r11 (caller-saved, general temp)
   139→        const temp_regs = [_]u4{ 10, 11 };
   140→        for (temp_regs) |reg_idx| {
   141→            if (!self.used_regs[reg_idx]) {
   142→                self.used_regs[reg_idx] = true;
   143→                return @enumFromInt(reg_idx);
   144→            }
   145→        }
   146→
   147→        // Then try arg registers: rax, rcx, rdx, rsi, rdi, r8, r9
   148→        const arg_regs = [_]u4{ 0, 1, 2, 6, 7, 8, 9 };
   149→        for (arg_regs) |reg_idx| {
   150→            if (!self.used_regs[reg_idx]) {
   151→                self.used_regs[reg_idx] = true;
   152→                return @enumFromInt(reg_idx);
   153→            }
   154→        }
   155→
   156→        // Finally try saved registers: rbx, r12, r13, r14, r15
   157→        const saved_regs = [_]u4{ 3, 12, 13, 14, 15 };
   158→        for (saved_regs) |reg_idx| {
   159→            if (!self.used_regs[reg_idx]) {
   160→                self.used_regs[reg_idx] = true;
   161→                return @enumFromInt(reg_idx);
   162→            }
   163→        }
   164→
   165→        return null;
   166→    }
   167→
   168→    // Free a register
   169→    pub fn freeReg(self: *X86_64Codegen, reg: Register) void {
   170→        self.used_regs[@intFromEnum(reg)] = false;
   171→    }
   172→
   173→    // Emit line to output
   174→    fn emit(self: *X86_64Codegen, comptime fmt: []const u8, args: anytype) !void {
   175→        try self.output.writer().print(fmt ++ "\n", args);
   176→    }
   177→
   178→    // Emit raw text
   179→    fn emitRaw(self: *X86_64Codegen, text: []const u8) !void {
   180→        try self.output.appendSlice(text);
   181→        try self.output.append('\n');
   182→    }
   183→
   184→    // === Step 1: Basic Arithmetic Instructions ===
   185→
   186→    /// mov dst, imm64  (Move Immediate)
   187→    /// Note: x86-64 mov cannot directly load 64-bit immediates,
   188→    /// so we use: mov rax, imm64 (zig/assembler pseudo-op)
   189→    /// or: movabs rax, 0x123456789abcdef0
   190→    fn emitMovImm(self: *X86_64Codegen, dst: Register, value: i64) !void {
   191→        if (value >= -2147483648 and value <= 2147483647) {
   192→            // Fits in 32-bit signed
   193→            try self.emit("    mov {s}, {}", .{ dst.name(), value });
   194→        } else {
   195→            // Need movabs for 64-bit
   196→            try self.emit("    movabs {s}, 0x{x}", .{ dst.name(), @as(u64, @bitCast(value)) });
   197→        }
   198→    }
   199→
   200→    /// mov dst, src  (Move Register)
   201→    fn emitMov(self: *X86_64Codegen, dst: Register, src: Register) !void {
   202→        try self.emit("    mov {s}, {s}", .{ dst.name(), src.name() });
   203→    }
   204→
   205→    /// add dst, src  (Addition: dst += src)
   206→    fn emitAdd(self: *X86_64Codegen, dst: Register, src: Register) !void {
   207→        try self.emit("    add {s}, {s}", .{ dst.name(), src.name() });
   208→    }
   209→
   210→    /// sub dst, src  (Subtraction: dst -= src)
   211→    fn emitSub(self: *X86_64Codegen, dst: Register, src: Register) !void {
   212→        try self.emit("    sub {s}, {s}", .{ dst.name(), src.name() });
   213→    }
   214→
   215→    /// imul dst, src  (Signed Multiplication: dst *= src)
   216→    fn emitImul(self: *X86_64Codegen, dst: Register, src: Register) !void {
   217→        try self.emit("    imul {s}, {s}", .{ dst.name(), src.name() });
   218→    }
   219→
   220→    /// idiv src  (Signed Division: rdx:rax / src, result in rax, remainder in rdx)
   221→    /// Precondition: rax must contain the dividend
   222→    fn emitIdiv(self: *X86_64Codegen, src: Register) !void {
   223→        try self.emit("    idiv {s}", .{src.name()});
   224→    }
   225→
   226→    /// cqo  (Sign-extend rax into rdx:rax for 64-bit idiv)
   227→    fn emitCqo(self: *X86_64Codegen) !void {
   228→        try self.emitRaw("    cqo");
   229→    }
   230→
   231→    /// neg dst  (Negation: dst = -dst)
   232→    fn emitNeg(self: *X86_64Codegen, dst: Register) !void {
   233→        try self.emit("    neg {s}", .{dst.name()});
   234→    }
   235→
   236→    /// cmp lhs, rhs  (Compare: set flags based on lhs - rhs)
   237→    fn emitCmp(self: *X86_64Codegen, lhs: Register, rhs: Register) !void {
   238→        try self.emit("    cmp {s}, {s}", .{ lhs.name(), rhs.name() });
   239→    }
   240→
   241→    /// sete dst  (Set if Equal: dst = (ZF == 1))
   242→    fn emitSete(self: *X86_64Codegen, dst: Register) !void {
   243→        try self.emit("    sete {s}", .{dst.al()});
   244→    }
   245→
   246→    /// setne dst  (Set if Not Equal)
   247→    fn emitSetne(self: *X86_64Codegen, dst: Register) !void {
   248→        try self.emit("    setne {s}", .{dst.al()});
   249→    }
   250→
   251→    /// setl dst  (Set if Less, signed)
   252→    fn emitSetl(self: *X86_64Codegen, dst: Register) !void {
   253→        try self.emit("    setl {s}", .{dst.al()});
   254→    }
   255→
   256→    /// setle dst  (Set if Less or Equal, signed)
   257→    fn emitSetle(self: *X86_64Codegen, dst: Register) !void {
   258→        try self.emit("    setle {s}", .{dst.al()});
   259→    }
   260→
   261→    /// setg dst  (Set if Greater, signed)
   262→    fn emitSetg(self: *X86_64Codegen, dst: Register) !void {
   263→        try self.emit("    setg {s}", .{dst.al()});
   264→    }
   265→
   266→    /// setge dst  (Set if Greater or Equal, signed)
   267→    fn emitSetge(self: *X86_64Codegen, dst: Register) !void {
   268→        try self.emit("    setge {s}", .{dst.al()});
   269→    }
   270→
   271→    /// movzx dst, src  (Move with Zero Extension: dst = (u64)src)
   272→    /// Used after setX to zero-extend 8-bit result to 64-bit
   273→    fn emitMovzx(self: *X86_64Codegen, dst: Register, src_byte: []const u8) !void {
   274→        try self.emit("    movzx {s}, {s}", .{ dst.name(), src_byte });
   275→    }
   276→
   277→    /// ret  (Return from function)
   278→    fn emitRet(self: *X86_64Codegen) !void {
   279→        try self.emitRaw("    ret");
   280→    }
   281→
   282→    // === Step 2: Function & Stack Management ===
   283→
   284→    /// Function prologue (System V AMD64 ABI)
   285→    /// Preserves rbp and sets up stack frame
   286→    fn emitFunctionPrologue(self: *X86_64Codegen, frame_size: i64) !void {
   287→        self.current_frame_size = frame_size;
   288→        // 16-byte align: frame_size should be multiple of 16
   289→        const aligned_frame = ((frame_size + 15) / 16) * 16;
   290→        try self.emitRaw("    push rbp");
   291→        try self.emitRaw("    mov rbp, rsp");
   292→        if (aligned_frame > 0) {
   293→            try self.emit("    sub rsp, {}", .{aligned_frame});
   294→        }
   295→    }
   296→
   297→    /// Function epilogue
   298→    fn emitFunctionEpilogue(self: *X86_64Codegen) !void {
   299→        const aligned_frame = ((self.current_frame_size + 15) / 16) * 16;
   300→        if (aligned_frame > 0) {
   301→            try self.emit("    add rsp, {}", .{aligned_frame});
   302→        }
   303→        try self.emitRaw("    pop rbp");
   304→        try self.emitRet();
   305→    }
   306→
   307→    /// Store to memory: mov QWORD [rbp-offset], src
   308→    fn emitMovToMem(self: *X86_64Codegen, offset: i64, src: Register) !void {
   309→        try self.emit("    mov QWORD [rbp-{}], {s}", .{ offset, src.name() });
   310→    }
   311→
   312→    /// Load from memory: mov dst, QWORD [rbp-offset]
   313→    fn emitMovFromMem(self: *X86_64Codegen, dst: Register, offset: i64) !void {
   314→        try self.emit("    mov {s}, QWORD [rbp-{}]", .{ dst.name(), offset });
   315→    }
   316→
   317→    /// call target  (Function Call)
   318→    fn emitCall(self: *X86_64Codegen, target: []const u8) !void {
   319→        try self.emit("    call {s}", .{target});
   320→    }
   321→
   322→    /// .globl name  (Global Symbol Declaration)
   323→    fn emitGlobal(self: *X86_64Codegen, name: []const u8) !void {
   324→        try self.emit("global {s}", .{name});
   325→    }
   326→
   327→    /// name:  (Function Label)
   328→    fn emitFunctionLabel(self: *X86_64Codegen, name: []const u8) !void {
   329→        try self.emit("{}:", .{name});
   330→    }
   331→
   332→    // === Step 3: Control Flow ===
   333→
   334→    /// Generate new label
   335→    fn newLabel(self: *X86_64Codegen, allocator: Allocator) ![]u8 {
   336→        defer self.label_counter += 1;
   337→        return std.fmt.allocPrint(allocator, ".L{}", .{self.label_counter});
   338→    }
   339→
   340→    /// Emit label
   341→    fn emitLabel(self: *X86_64Codegen, label: []const u8) !void {
   342→        try self.emit("{}:", .{label});
   343→    }
   344→
   345→    /// Unconditional jump
   346→    fn emitJmp(self: *X86_64Codegen, label: []const u8) !void {
   347→        try self.emit("    jmp {}", .{label});
   348→    }
   349→
   350→    /// je label  (Jump if Equal, ZF=1)
   351→    fn emitJe(self: *X86_64Codegen, label: []const u8) !void {
   352→        try self.emit("    je {}", .{label});
   353→    }
   354→
   355→    /// jne label  (Jump if Not Equal, ZF=0)
   356→    fn emitJne(self: *X86_64Codegen, label: []const u8) !void {
   357→        try self.emit("    jne {}", .{label});
   358→    }
   359→
   360→    /// jl label  (Jump if Less, signed: SF != OF)
   361→    fn emitJl(self: *X86_64Codegen, label: []const u8) !void {
   362→        try self.emit("    jl {}", .{label});
   363→    }
   364→
   365→    /// jle label  (Jump if Less or Equal, signed)
   366→    fn emitJle(self: *X86_64Codegen, label: []const u8) !void {
   367→        try self.emit("    jle {}", .{label});
   368→    }
   369→
   370→    /// jg label  (Jump if Greater, signed)
   371→    fn emitJg(self: *X86_64Codegen, label: []const u8) !void {
   372→        try self.emit("    jg {}", .{label});
   373→    }
   374→
   375→    /// jge label  (Jump if Greater or Equal, signed)
   376→    fn emitJge(self: *X86_64Codegen, label: []const u8) !void {
   377→        try self.emit("    jge {}", .{label});
   378→    }
   379→
   380→    /// jz label  (Jump if Zero, alias for je)
   381→    fn emitJz(self: *X86_64Codegen, label: []const u8) !void {
   382→        try self.emit("    jz {}", .{label});
   383→    }
   384→
   385→    /// jnz label  (Jump if Not Zero, alias for jne)
   386→    fn emitJnz(self: *X86_64Codegen, label: []const u8) !void {
   387→        try self.emit("    jnz {}", .{label});
   388→    }
   389→
   390→    /// test reg, reg  (Test: sets flags based on bitwise AND)
   391→    fn emitTest(self: *X86_64Codegen, reg: Register) !void {
   392→        try self.emit("    test {s}, {s}", .{ reg.name(), reg.name() });
   393→    }
   394→
   395→    // === Main Code Generation ===
   396→
   397→    pub fn generate(self: *X86_64Codegen, air: Air, output_file: []const u8) !void {
   398→        try self.emitRaw("section .text");
   399→
   400→        // Process AIR instructions
   401→        for (air.instructions.items) |instr| {
   402→            try self.processInstruction(instr);
   403→        }
   404→
   405→        // Write output file
   406→        const file = try std.fs.cwd().createFile(output_file, .{});
   407→        defer file.close();
   408→        try file.writeAll(self.output.items);
   409→    }
   410→
   411→    fn processInstruction(self: *X86_64Codegen, instr: Instruction) !void {
   412→        switch (instr) {
   413→            .noop => {
   414→                // No operation
   415→            },
   416→            .load_int => |value| {
   417→                if (self.allocReg()) |reg| {
   418→                    try self.emitMovImm(reg, value);
   419→                    defer self.freeReg(reg);
   420→                }
   421→            },
   422→            .binary_op => |binop| {
   423→                if (self.allocReg()) |dst| {
   424→                    defer self.freeReg(dst);
   425→                    if (self.allocReg()) |src| {
   426→                        defer self.freeReg(src);
   427→
   428→                        switch (binop.op) {
   429→                            .add => try self.emitAdd(dst, src),
   430→                            .sub => try self.emitSub(dst, src),
   431→                            .mul => try self.emitImul(dst, src),
   432→                            .div => {
   433→                                try self.emitCqo();
   434→                                try self.emitIdiv(src);
   435→                            },
   436→                            .mod => {
   437→                                try self.emitCqo();
   438→                                try self.emitIdiv(src);
   439→                                // Result in rdx, need to move it to dst
   440→                            },
   441→                            .eq => {
   442→                                try self.emitCmp(dst, src);
   443→                                try self.emitSete(dst);
   444→                                try self.emitMovzx(dst, dst.al());
   445→                            },
   446→                            .ne => {
   447→                                try self.emitCmp(dst, src);
   448→                                try self.emitSetne(dst);
   449→                                try self.emitMovzx(dst, dst.al());
   450→                            },
   451→                            .lt => {
   452→                                try self.emitCmp(dst, src);
   453→                                try self.emitSetl(dst);
   454→                                try self.emitMovzx(dst, dst.al());
   455→                            },
   456→                            .le => {
   457→                                try self.emitCmp(dst, src);
   458→                                try self.emitSetle(dst);
   459→                                try self.emitMovzx(dst, dst.al());
   460→                            },
   461→                            .gt => {
   462→                                try self.emitCmp(dst, src);
   463→                                try self.emitSetg(dst);
   464→                                try self.emitMovzx(dst, dst.al());
   465→                            },
   466→                            .ge => {
   467→                                try self.emitCmp(dst, src);
   468→                                try self.emitSetge(dst);
   469→                                try self.emitMovzx(dst, dst.al());
   470→                            },
   471→                        }
   472→                    }
   473→                }
   474→            },
   475→            .unary_op => |uop| {
   476→                if (self.allocReg()) |dst| {
   477→                    defer self.freeReg(dst);
   478→                    switch (uop.op) {
   479→                        .negate => try self.emitNeg(dst),
   480→                        .not => {
   481→                            try self.emitTest(dst);
   482→                            try self.emitSete(dst);
   483→                            try self.emitMovzx(dst, dst.al());
   484→                        },
   485→                    }
   486→                }
   487→            },
   488→            .function_begin => |func| {
   489→                try self.emitGlobal(func.name);
   490→                try self.emitFunctionLabel(func.name);
   491→                // Calculate frame size (push rbp makes 16-byte offset, so add minimum locals)
   492→                const frame_size = 32;
   493→                try self.emitFunctionPrologue(frame_size);
   494→            },
   495→            .function_end => {
   496→                try self.emitFunctionEpilogue();
   497→            },
   498→            else => {},
   499→        }
   500→    }
   501→};
   502→
   503→// ============================================================================
   504→// Public API
   505→// ============================================================================
   506→
   507→pub fn main() !void {
   508→    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
   509→    defer _ = gpa.deinit();
   510→    const allocator = gpa.allocator();
   511→
   512→    std.debug.print("x86-64 Code Generator initialized\n", .{});
   513→}
