     1→/// RISC-V Code Generator for Zig Compiler
     2→/// Converts AIR (Analyzed IR) to RISC-V Assembly
     3→///
     4→/// Architecture:
     5→/// - AIR instructions → RISC-V assembly (.s file)
     6→/// - Register allocation: x0-x31 (32 registers)
     7→/// - Calling convention: RISC-V ABI (a0-a7 for args, a0 for return)
     8→
     9→const std = @import("std");
    10→const Allocator = std.mem.Allocator;
    11→const ArrayList = std.ArrayList;
    12→const StringHashMap = std.StringHashMap;
    13→
    14→// ============================================================================
    15→// AIR Types (假설: 기존 컴파일러에서 정의됨)
    16→// ============================================================================
    17→
    18→pub const Air = struct {
    19→    ref_type: type,
    20→    instructions: ArrayList(Instruction),
    21→};
    22→
    23→pub const Instruction = union(enum) {
    24→    load_int: i64,
    25→    binary_op: struct {
    26→        op: BinaryOp,
    27→        lhs: u32, // ref
    28→        rhs: u32, // ref
    29→    },
    30→    unary_op: struct {
    31→        op: UnaryOp,
    32→        operand: u32,
    33→    },
    34→    function_begin: struct {
    35→        name: []const u8,
    36→        arg_count: u32,
    37→    },
    38→    function_end,
    39→    call: struct {
    40→        target: []const u8,
    41→        arg_count: u32,
    42→    },
    43→    cond_br: struct {
    44→        cond: u32,
    45→        then_label: u32,
    46→        else_label: u32,
    47→    },
    48→    br: u32, // label
    49→    label: u32,
    50→    noop,
    51→};
    52→
    53→pub const BinaryOp = enum {
    54→    add,
    55→    sub,
    56→    mul,
    57→    div,
    58→    mod,
    59→    eq,
    60→    ne,
    61→    lt,
