     1→/// Zig Compiler with Multi-Backend Support
     2→///
     3→/// Usage:
     4→/// zig-compiler --emit-riscv input.zig -o output.s
     5→/// zig-compiler --emit-x86-64 input.zig -o output.asm
     6→/// zig-compiler --help
     7→///
     8→/// Pipeline:
     9→/// Source (.zig) → Tokenizer → Parser (AST) → AstGen (ZIR) → Sema (AIR) → Codegen
    10→///                                                                      ↓
    11→///                                         ┌──────────────┬──────────────┐
    12→///                                         ↓              ↓
    13→///                                    RISC-V .s      x86-64 .asm
    14→
    15→const std = @import("std");
    16→const RiscvCodegen = @import("riscv_codegen.zig").RiscvCodegen;
    17→const X86_64Codegen = @import("x86_64_codegen.zig").X86_64Codegen;
    18→
    19→const Args = struct {
    20→    input_file: ?[]const u8 = null,
    21→    output_file: ?[]const u8 = null,
    22→    emit_riscv: bool = false,
    23→    emit_x86_64: bool = false,
    24→    emit_c: bool = false,
    25→    help: bool = false,
    26→};
    27→
    28→fn printUsage(program_name: []const u8) void {
    29→    std.debug.print(
    30→        \\Usage: {s} [options] <input-file>
    31→        \\
    32→        \\Options:
    33→        \\  -o, --output <file>      Output file path
    34→        \\  --emit-riscv              Generate RISC-V assembly (.s)
    35→        \\  --emit-x86-64             Generate x86-64 assembly (.asm, Intel syntax)
    36→        \\  --emit-c                  Generate C code (.c) [default]
    37→        \\  -h, --help                Print this help message
    38→        \\
    39→        \\Examples:
    40→        \\  {s} --emit-riscv test.zig -o test.s
    41→        \\  {s} --emit-x86-64 test.zig -o test.asm
    42→        \\  {s} --emit-c test.zig -o test.c
    43→        \\
    44→        \\Compiler Version: 0.5.0 (Phase 5: x86-64 Backend)
    45→        \\
    46→    , .{ program_name, program_name, program_name, program_name });
    47→}
    48→
    49→fn parseArgs(allocator: std.mem.Allocator, argv: [][]const u8) !Args {
    50→    var args = Args{};
    51→    var i: usize = 1; // Skip program name
    52→
    53→    while (i < argv.len) : (i += 1) {
    54→        const arg = argv[i];
    55→
    56→        if (std.mem.eql(u8, arg, "--help") or std.mem.eql(u8, arg, "-h")) {
    57→            args.help = true;
    58→        } else if (std.mem.eql(u8, arg, "--emit-riscv")) {
    59→            args.emit_riscv = true;
    60→        } else if (std.mem.eql(u8, arg, "--emit-x86-64")) {
    61→            args.emit_x86_64 = true;
    62→        } else if (std.mem.eql(u8, arg, "--emit-c")) {
    63→            args.emit_c = true;
    64→        } else if (std.mem.eql(u8, arg, "-o") or std.mem.eql(u8, arg, "--output")) {
    65→            i += 1;
    66→            if (i < argv.len) {
    67→                args.output_file = argv[i];
    68→            } else {
    69→                std.debug.print("Error: -o requires an argument\n", .{});
    70→                return error.MissingArgument;
    71→            }
    72→        } else if (std.mem.startsWith(u8, arg, "-")) {
    73→            std.debug.print("Error: Unknown option '{s}'\n", .{arg});
    74→            return error.UnknownOption;
    75→        } else {
    76→            // Input file
    77→            if (args.input_file == null) {
    78→                args.input_file = arg;
    79→            } else {
    80→                std.debug.print("Error: Multiple input files not supported\n", .{});
    81→                return error.MultipleInputFiles;
