    94→fn readInputFile(allocator: std.mem.Allocator, path: []const u8) ![]u8 {
    95→    const file = try std.fs.cwd().openFile(path, .{});
    96→    defer file.close();
    97→
    98→    const file_size = try file.getEndPos();
    99→    const content = try allocator.alloc(u8, file_size);
   100→    const bytes_read = try file.readAll(content);
   101→
   102→    if (bytes_read != file_size) {
   103→        return error.IncompleteRead;
   104→    }
   105→
   106→    return content;
   107→}
